var S=window.SugarCube, setup=S.setup, sv=S.State.variables;
try {
  var wikiOk = (typeof jQuery.fn.wiki === 'function');
  setup.openPhone();
  setup._renderCustom('c','xCam','Start');
  var customBody = (document.querySelector('#phone-custom-body')||{}).innerHTML || '';
  var customRendered = customBody.length > 0 && customBody.indexOf('Unavailable') === -1 && customBody.indexOf('Missing') === -1;
  sv.player = sv.player || {}; sv.player.core_traits = sv.player.core_traits || {}; sv.player.core_traits.corruption = 0;
  setup.phone_data.gallery_items = [
    {id:'free', image:'a.jpg', caption:'free'},
    {id:'locked', image:'b.jpg', caption:'locked', trigger:{version:'1.0', items:[{type:'corruption_level',operator:'gte',value:3}]}, link:'Start'}
  ];
  setup._renderGallery('g','Gallery');
  var cells0 = document.querySelectorAll('.phone-gallery-cell').length;
  sv.player.core_traits.corruption = 30;
  setup._renderGallery('g','Gallery');
  var cells30 = document.querySelectorAll('.phone-gallery-cell').length;
  var linkCells = document.querySelectorAll('.phone-gallery-link').length;
  return JSON.stringify({wikiOk:wikiOk, customRendered:customRendered, customLen:customBody.length, cells_corr0:cells0, cells_corr30:cells30, clickableLinks:linkCells});
} catch(e){ return JSON.stringify({error:String(e)}); }

var S=window.SugarCube, setup=S.setup, sv=S.State.variables;
try {
  sv.player.core_traits.corruption = 0;
  // CORRECT shape: trigger.conditions = {version, items}  (matches posts/conversations)
  setup.phone_data.gallery_items = [
    {id:'free', image:'a.jpg'},
    {id:'locked', image:'b.jpg', link:'Start', trigger:{conditions:{version:'1.0', items:[{type:'corruption_level',operator:'gte',value:3}]}}}
  ];
  setup._renderGallery('g','Gallery');
  var c0 = document.querySelectorAll('.phone-gallery-cell').length;
  sv.player.core_traits.corruption = 30;
  setup._renderGallery('g','Gallery');
  var c30 = document.querySelectorAll('.phone-gallery-cell').length;
  return JSON.stringify({cells_corr0:c0, cells_corr30:c30});
} catch(e){ return JSON.stringify({error:String(e)}); }

var S=window.SugarCube, st=S.State, setup=S.setup;
try {
  // get into a real gameplay passage so advanceDay's full pipeline has state
  if (S.Story.has('Bedroom')) S.Engine.play('Bedroom'); else S.Engine.play(S.Config.passages.start);
  var sv = st.variables;
  sv.game_state = sv.game_state || {};
  sv.game_state.scheduled = [{daysLeft:1, action:'set_flag', flag:'sched_fire'}];
  sv.game_state.fast_jobs = {xp:0, cooldowns:{dog:2}};
  sv.game_state.bank = {balance:100};
  setup.bank_data = {interest_rate:0.1, money_trait:'money'};
  sv.flags = sv.flags || {};
  var before = {sched:sv.game_state.scheduled.length, cd:sv.game_state.fast_jobs.cooldowns.dog, bal:sv.game_state.bank.balance};
  window.advanceDay();
  var after = {schedFired: !!sv.flags.sched_fire, schedLen: sv.game_state.scheduled.length, cd: sv.game_state.fast_jobs.cooldowns.dog, bal: sv.game_state.bank.balance};
  return JSON.stringify({before:before, after:after});
} catch(e){ return JSON.stringify({error:String(e)}); }
